/*
 * Build js/lang-detect.js.
 *
 * Run: npm run build:lang
 *
 * Bundles a trimmed Efficient Language Detector (ELD) database with the small
 * wrapper in scripts/lang-detect-entry.js. Only the eight Latin-script UI
 * languages are included; ru/zh/ja/ko/ar/he/el/th/hi are resolved by Unicode
 * script before ELD is consulted, so bundling their n-gram models would be
 * wasted bytes on a Kindle.
 *
 * The generated file is committed: deploys copy source files, and CI does not
 * need to install a 9 MB dev dependency just to ship a static asset. Re-run this
 * script whenever `eld` is upgraded, then run `node scripts/test-lang-detect.js`.
 */
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const { pathToFileURL } = require('url');
const esbuild = require('esbuild');

const root = path.join(__dirname, '..');
const outFile = path.join(root, 'js', 'lang-detect.js');
const LATIN_LANGS = ['en', 'de', 'es', 'fr', 'it', 'pl', 'pt', 'vi'];
const ELD_VERSION = JSON.parse(fs.readFileSync(path.join(root, 'node_modules', 'eld', 'package.json'), 'utf8')).version;

async function loadNgrams() {
    const url = pathToFileURL(path.join(root, 'node_modules', 'eld', 'src', 'ngrams', 'medium.js')).href;
    const mod = await import(url);
    return mod.ngramsData;
}

function makeSubset(data) {
    const oldIds = Object.keys(data.languages)
        .filter(id => LATIN_LANGS.indexOf(data.languages[id]) !== -1)
        .map(Number);
    if (oldIds.length !== LATIN_LANGS.length) {
        throw new Error('eld database is missing one of: ' + LATIN_LANGS.join(', '));
    }
    const remap = {};
    oldIds.forEach((oldId, index) => { remap[oldId] = index; });

    const languages = {};
    oldIds.forEach((oldId, index) => { languages[index] = data.languages[oldId]; });

    const ngrams = {};
    for (const ngram in data.ngrams) {
        if (!Object.prototype.hasOwnProperty.call(data.ngrams, ngram)) continue;
        const row = {};
        let any = false;
        for (const oldId of oldIds) {
            if (data.ngrams[ngram][oldId] !== undefined) {
                row[remap[oldId]] = data.ngrams[ngram][oldId];
                any = true;
            }
        }
        if (any) ngrams[ngram] = row;
    }

    return {
        type: 'RK-' + data.type + '-latin8',
        languages,
        isSubset: true,
        ngrams
    };
}

async function main() {
    const data = await loadNgrams();
    const subset = makeSubset(data);

    const result = await esbuild.build({
        entryPoints: [path.join(__dirname, 'lang-detect-entry.js')],
        bundle: true,
        format: 'iife',
        target: 'es2019',
        minify: true,
        legalComments: 'inline',
        charset: 'utf8',
        outfile: outFile,
        write: false,
        plugins: [{
            name: 'virtual-ngrams',
            setup(build) {
                build.onResolve({ filter: /^virtual:ngrams$/ }, () => ({ path: 'ngrams', namespace: 'virtual' }));
                build.onLoad({ filter: /.*/, namespace: 'virtual' }, () => ({
                    contents: 'export const ngramsData = ' + JSON.stringify(subset) + ';',
                    loader: 'js'
                }));
            }
        }]
    });

    const body = result.outputFiles[0].contents;
    const banner = [
        '/*!',
        ' * ReKindle language detection.',
        ' *',
        ' * Bundles the Efficient Language Detector (ELD) ' + ELD_VERSION + ' by Nito T.M.,',
        ' * Apache License 2.0 - https://github.com/nitotm/efficient-language-detector-js',
        ' * Full licence: licenses/efficient-language-detector-LICENSE.txt',
        ' *',
        ' * Generated by scripts/build-lang-detect.js from scripts/lang-detect-entry.js.',
        ' * Do not edit by hand: run `npm run build:lang` instead.',
        ' */',
        ''
    ].join('\n');

    fs.writeFileSync(outFile, banner + Buffer.from(body).toString('utf8') + '\n');
    const bytes = fs.statSync(outFile).size;
    const gzip = zlib.gzipSync(fs.readFileSync(outFile)).length;
    console.log('Wrote ' + path.relative(root, outFile) + ': ' + Math.round(bytes / 1024) + ' KB raw, ' +
        Math.round(gzip / 1024) + ' KB gzip (' + Object.keys(subset.ngrams).length + ' n-grams, ' +
        Object.keys(subset.languages).length + ' languages)');
}

main().catch(err => {
    console.error(err);
    process.exit(1);
});
